/**
 * The v4 protocol codec against the independent vectors.
 *
 * `tests/SmartAccount.Native.Tests/TestFile/smartaccount-v4-vectors.json` is
 * generated by a Python script written from the specification alone, not from
 * the C# kernels. If the SDK and that script disagree, the SDK is wrong: these
 * are the bytes a signature covers and the chain recomputes.
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { nativeCodec: c, PROTOCOL_VERSION } = require('../src/native');

const vectors = JSON.parse(
  fs.readFileSync(
    path.join(
      __dirname,
      '../../..',
      'tests/SmartAccount.Native.Tests/TestFile/smartaccount-v4-vectors.json',
    ),
    'utf8',
  ),
);

const strip = (hash) => hash.replace(/^0x/i, '');
const NETWORK = vectors.network;
const CORE = strip(vectors.serviceHash);
const ACCOUNT_ID = strip(vectors.accountId);
const CUSTODY = strip(vectors.custody);
const SALT = vectors.salt;
const DEADLINE = '1700000000000';
const ZERO_SUBKEY = '00'.repeat(32);

/** The operation the vector pinned: ping with no arguments, empty signature. */
const operation = {
  targetContract: CORE,
  method: 'ping',
  args: [],
  nonce: 0,
  nonceSubkey: ZERO_SUBKEY,
  deadline: DEADLINE,
  validatorId: 0,
  credentialGeneration: 0,
  authorityEpoch: 1,
  configurationNonce: 0,
  signature: '',
};
const context = {
  networkMagic: NETWORK,
  coreContractHash: CORE,
  accountId: ACCOUNT_ID,
};

/** Byte helpers used to rebuild a digest layout by hand, independently of the codec. */
const sha256 = (hex) =>
  require('node:crypto').createHash('sha256').update(Buffer.from(hex, 'hex')).digest('hex');
const reverseBytes = (hex) => Buffer.from(hex, 'hex').reverse();
const le32 = (value) => {
  const buffer = Buffer.alloc(4);
  buffer.writeUInt32LE(value);
  return buffer;
};
const be64 = (value) => {
  const buffer = Buffer.alloc(8);
  buffer.writeBigUInt64BE(BigInt(value));
  return buffer;
};

test('identity, proxy script and proxy address match the independent vector', () => {
  const identity = c.deriveIdentity({
    custodyAddress: CUSTODY,
    salt: SALT,
    coreContractHash: CORE,
    callFlags: 5,
  });
  assert.equal(identity.accountId, ACCOUNT_ID);
  assert.equal(identity.verificationScript, vectors.verificationScript);
  assert.equal(identity.accountAddress, strip(vectors.proxyAddress));
  // The custom kernel pushes CallFlags.All; the flag is identity, never inferred.
  assert.notEqual(
    c.accountAddress(ACCOUNT_ID, { coreContractHash: CORE, callFlags: 15 }),
    identity.accountAddress,
  );
});

test('the canonical thirteen-field operation and its digest match the vector', () => {
  assert.equal(c.protocolVersion, PROTOCOL_VERSION);
  assert.equal(PROTOCOL_VERSION, 4);
  assert.equal(c.serializeOperation(operation, true), vectors.operation.canonical);
  assert.equal(c.operationDigest(context, operation), vectors.operation.digest);
  // The signature is not part of the digest: a signed operation signs the same bytes.
  assert.equal(
    c.operationDigest(context, { ...operation, signature: '11'.repeat(64) }),
    vectors.operation.digest,
  );
});

test('every independently generated routing digest matches', () => {
  const cases = [
    ['epoch2', { authorityEpoch: 2 }],
    ['nonce1', { configurationNonce: 1 }],
    ['validator1', { validatorId: 1 }],
    ['subkey1', { nonceSubkey: 'ee'.repeat(32) }],
  ];
  for (const [name, patch] of cases) {
    const op = { ...operation, ...patch };
    assert.equal(c.operationDigest(context, op), vectors.digests[name], name);
  }
  // One changed routing field must change the digest: the domain binds all four.
  const digests = new Set([
    vectors.operation.digest,
    ...Object.values(vectors.digests),
  ]);
  assert.equal(digests.size, 5);
});

test('the digest domain is the §4.3 layout, network little-endian', () => {
  const domain = Buffer.concat([
    Buffer.from('NeoSmartAccount/UserOperation'),
    Buffer.from([4, NETWORK & 0xff, (NETWORK >>> 8) & 0xff, (NETWORK >>> 16) & 0xff, NETWORK >>> 24]),
    Buffer.from(CORE, 'hex').reverse(),
    Buffer.from(ACCOUNT_ID, 'hex').reverse(),
    Buffer.from('0000000000000000', 'hex'),
    Buffer.from('0000000000000000', 'hex'),
    Buffer.from('0000000000000001', 'hex'),
    Buffer.from('0000000000000000', 'hex'),
  ]).toString('hex');
  assert.equal(c.operationDomain(context, operation), domain);
  assert.equal(
    c.operationPreimage(context, operation),
    domain + vectors.operation.canonical,
  );
});

test('the message digest binds sender, hash and authority epoch', () => {
  const message = {
    originalSender: CUSTODY,
    hash: 'ab'.repeat(32),
  };
  const base = c.messageDigest(
    { ...context, authorityEpoch: 1 },
    { ...message, validatorId: 0, credentialGeneration: 0 },
  );
  assert.match(base, /^[0-9a-f]{64}$/);
  const other = c.messageDigest(
    { ...context, authorityEpoch: 2 },
    { ...message, validatorId: 0, credentialGeneration: 0 },
  );
  assert.notEqual(base, other);
  assert.notEqual(
    c.messageDigest({ ...context, authorityEpoch: 1 }, { ...message, hash: 'ac'.repeat(32) }),
    base,
  );
  assert.notEqual(
    c.messageDigest(
      { ...context, authorityEpoch: 1 },
      { ...message, originalSender: CORE },
    ),
    base,
  );
  // The §8 layout is rebuilt here by hand: domain ‖ U1(version) ‖ U32LE(network)
  // ‖ core ‖ accountId ‖ sender ‖ U64BE(validator, generation, epoch) ‖ hash.
  assert.equal(
    base,
    sha256(
      Buffer.concat([
        Buffer.from('NeoSmartAccount/Message', 'utf8'),
        Buffer.from([4]),
        le32(NETWORK),
        reverseBytes(CORE),
        reverseBytes(ACCOUNT_ID),
        reverseBytes(CUSTODY),
        be64(0),
        be64(0),
        be64(1),
        Buffer.from('ab'.repeat(32), 'hex'),
      ]).toString('hex'),
    ),
  );
  // A message without a sender or hash cannot be bound to an account.
  assert.throws(
    () => c.messageDigest({ ...context, authorityEpoch: 1 }, { originalSender: CUSTODY }),
    /hex bytes/,
  );
  assert.throws(
    () => c.messageDigest({ ...context, authorityEpoch: 1 }, { hash: 'ab'.repeat(32) }),
    /hex bytes/,
  );
});

test('nonce channels are 191-bit namespaces derived from the routing tuple', () => {
  const routing = {
    authorityEpoch: 1,
    validatorId: 0,
    credentialGeneration: 1,
    nonceSubkey: ZERO_SUBKEY,
  };
  // The epoch is part of the namespace context, the rest is the routing tuple.
  const nonceContext = { ...context, authorityEpoch: 1 };
  const channel = c.deriveNonceChannel(nonceContext, routing);
  assert.equal(BigInt(channel) < 1n << 191n, true);
  assert.equal(c.nonceNamespaceDigest(nonceContext, routing).length, 64);
  const variants = [
    { ...routing, authorityEpoch: 2 },
    { ...routing, validatorId: 1 },
    { ...routing, credentialGeneration: 2 },
    { ...routing, nonceSubkey: 'ee'.repeat(32) },
  ];
  for (const variant of variants) {
    assert.notEqual(
      c.deriveNonceChannel({ ...nonceContext, ...variant }, variant),
      channel,
    );
  }
  // A subkey is exactly 32 bytes.
  assert.throws(
    () => c.deriveNonceChannel(nonceContext, { ...routing, nonceSubkey: '00' }),
    /hex byte length/,
  );
});

test('packed nonce round-trips and enforces both widths', () => {
  const channel = (1n << 191n) - 1n;
  const sequence = (1n << 64n) - 1n;
  assert.deepEqual(c.splitNonce(c.composeNonce(channel, sequence)), {
    channel,
    sequence,
  });
  assert.equal(c.composeNonce(channel, sequence), (1n << 255n) - 1n);
  assert.throws(() => c.composeNonce(1n << 191n, 0));
  assert.throws(() => c.composeNonce(0, 1n << 64n));
  assert.throws(() => c.composeNonce(0, Number.MAX_SAFE_INTEGER + 1));
  assert.throws(() => c.splitNonce(1n << 255n));
});

test('argument values are canonical: no Struct, no Map, no shared references', () => {
  const base = { ...operation, args: [] };
  const serialize = (args) => c.serializeOperation({ ...base, args }, true);
  assert.equal(serialize([{ type: 'Boolean', value: true }]), serialize([{ type: 'Boolean', value: true }]));
  assert.notEqual(
    serialize([{ type: 'Array', value: [] }]),
    serialize([{ type: 'Null' }]),
  );
  for (const args of [
    [{ type: 'Map', value: [] }],
    // §4.1 admits Null, Boolean, Integer, ByteString and Array only: a Struct
    // anywhere in the operation is rejected, not carried alongside Array.
    [{ type: 'Struct', value: [] }],
    [{ type: 'Array', value: [{ type: 'Struct', value: [] }] }],
    [{ type: 'Boolean', value: 1 }],
    [{ type: 'Integer', value: 1.5 }],
    [{ type: 'ByteString', value: 'a' }],
    [{ type: 'Buffer', value: 'aa' }],
    [{ type: 'Any', value: 0 }],
  ]) {
    assert.throws(() => serialize(args), `rejects ${JSON.stringify(args)}`);
  }
  const shared = { type: 'Array', value: [] };
  assert.throws(() => serialize([shared, shared]), /shared reference/);
  const cycle = { type: 'Array', value: [] };
  cycle.value.push(cycle);
  assert.throws(() => serialize([cycle]));
  let deep = { type: 'Null' };
  for (let index = 0; index < 9; index += 1) deep = { type: 'Array', value: [deep] };
  assert.throws(() => serialize([deep]), /depth/);
});

test('operation bounds: method, target, subkey, deadline, signature, hook proofs', () => {
  // A signed operation carries a signature; the unsigned form empties it.
  const op = { ...operation, signature: '11'.repeat(64) };
  assert.equal(c.serializeOperation({ ...op, signature: '' }, true), vectors.operation.canonical);
  assert.throws(() => c.serializeOperation({ ...op, signature: '' }), /signature/);
  assert.throws(() => c.serializeOperation({ ...op, targetContract: '00'.repeat(20) }), /zero target/);
  assert.throws(() => c.serializeOperation({ ...op, method: '' }), /method/);
  assert.throws(() => c.serializeOperation({ ...op, method: '\ud800' }), /Unicode/);
  assert.throws(() => c.serializeOperation({ ...op, nonceSubkey: '00' }), /hex byte length/);
  assert.throws(() => c.serializeOperation({ ...op, nonce: 1n << 255n }), /uint255/);
  assert.throws(() => c.serializeOperation({ ...op, deadline: -1 }), /uint255/);
  assert.throws(() => c.serializeOperation({ ...op, signature: 'aa'.repeat(8193) }), /8192/);
  // Hook proofs: strictly ascending ids, individually and in aggregate bounded.
  assert.ok(
    c.serializeOperation({
      ...op,
      hookProofs: [
        { hookId: 1, proof: 'aa' },
        { hookId: 2, proof: 'bb' },
      ],
    }),
  );
  assert.throws(() =>
    c.serializeOperation({
      ...op,
      hookProofs: [
        { hookId: 2, proof: 'aa' },
        { hookId: 1, proof: 'bb' },
      ],
    }),
  /ascending/);
  assert.throws(() =>
    c.serializeOperation({
      ...op,
      hookProofs: [{ hookId: 1, proof: 'aa' }, { hookId: 1, proof: 'bb' }],
    }),
  /ascending/);
  assert.throws(() =>
    c.serializeOperation({
      ...op,
      hookProofs: [{ hookId: 1, proof: 'aa'.repeat(4097) }],
    }),
  /4096/);
});

test('built-in and threshold signature fields are serialized, not hashed', () => {
  const builtIn = c.builtInSignature({
    credentialGeneration: 1,
    pairs: [
      { script: '0c2102' + '11'.repeat(32) + '4156e7b327', signature: 'aa'.repeat(64) },
    ],
  });
  assert.match(builtIn, /^40/);
  assert.throws(
    () =>
      c.builtInSignature({
        credentialGeneration: 1,
        pairs: [
          { script: '0c21' + '11'.repeat(32) + '4156e7b327', signature: 'aa'.repeat(64) },
          { script: '0c21' + '11'.repeat(32) + '4156e7b327', signature: 'bb'.repeat(64) },
        ],
      }),
    /distinct/,
  );
  const memberDigest = c.thresholdMemberDigest(vectors.operation.digest, 1, 2);
  assert.match(memberDigest, /^[0-9a-f]{64}$/);
  const threshold = c.thresholdSignature([
    { moduleId: 1, signature: 'aa'.repeat(64) },
    { moduleId: 3, signature: 'bb'.repeat(64) },
  ]);
  assert.match(threshold, /^40/);
  assert.throws(
    () =>
      c.thresholdSignature([
        { moduleId: 3, signature: 'aa'.repeat(64) },
        { moduleId: 1, signature: 'bb'.repeat(64) },
      ]),
    /ascending/,
  );
});

test('execution scripts embed the operation and refuse another account', () => {
  const signedOp = { ...operation, signature: '11'.repeat(64) };
  const single = c.buildExecutionScript(ACCOUNT_ID, [signedOp], context);
  assert.ok(
    single.endsWith('41627d5b52'),
    'the script ends in the System.Contract.Call syscall',
  );
  assert.ok(single.includes('0c0d65786563757465557365724f70'));
  // An execution script carries the exact operation envelope: the unsigned
  // serialization of the signed operation is a substring of the script bytes.
  assert.ok(single.includes(c.encodeValue(c.operationValue(signedOp))));
  const batch = c.buildExecutionScript(
    ACCOUNT_ID,
    [signedOp, { ...signedOp, nonce: 1 }],
    context,
  );
  assert.notEqual(batch, single);
  assert.ok(batch.includes('0c0e65786563757465557365724f7073'));
  assert.throws(
    () =>
      c.buildExecutionScript(ACCOUNT_ID, [signedOp], {
        ...context,
        accountId: CUSTODY,
      }),
    /account mismatch/,
  );
  assert.throws(() => c.buildExecutionScript(ACCOUNT_ID, [], context));
  assert.throws(
    () => c.buildExecutionScript(ACCOUNT_ID, [operation], context),
    /signature/,
  );
});
